<section class="inner-hero admissions-hero"><div class="container"><span class="eyebrow eyebrow-light"><?= e($cmsPage['eyebrow']??'Admissions') ?></span><h1><?= e($cmsPage['title']??'Your next step, made clear.') ?></h1><p><?= e($cmsPage['excerpt']??'Explore published admission cycles, programmes, deadlines and configured requirements before beginning one secure application.') ?></p><div class="inner-hero-actions"><a class="button button-gold" href="#live-admissions">View admission cycles</a><a class="button button-ghost" href="<?= url('login') ?>">Applicant sign in</a></div></div></section>
<section class="section" id="live-admissions"><div class="container"><div class="section-heading split-heading"><div><span class="eyebrow">Published opportunities</span><h2>Admission cycles</h2></div><p>Status and deadlines are calculated from the server time. Draft, expired, closed and archived cycles are never offered for application.</p></div><?php if(!$cycles):?><div class="card empty-state"><span>⌛</span><h2>No published admission cycle is available</h2><p>Please check notices or contact Admissions for the next announced window.</p></div><?php else:?><div class="programme-grid admission-cycle-grid"><?php foreach($cycles as $cycle):?><article class="programme-card admission-cycle-card"><div class="programme-copy"><span class="status-pill status-<?= e($cycle['effective_status']) ?>"><?= e(ucwords(str_replace('_',' ',$cycle['effective_status']))) ?></span><h3><?= e($cycle['name']) ?></h3><p><?= e($cycle['summary']?:'Review programmes, eligibility, documents, fees and important dates for this admission cycle.') ?></p><ul><li><?= number_format((int)$cycle['program_count']) ?> configured programme<?= (int)$cycle['program_count']===1?'':'s' ?></li><li><?= number_format((int)$cycle['total_seats']) ?> configured seats</li><li>Application fee from <?= money($cycle['application_fee_from']) ?></li></ul><div class="programme-meta"><span><small>Opens</small><b><?= format_date($cycle['starts_at'],true) ?></b></span><span><small>Deadline</small><b><?= format_date($cycle['ends_at'],true) ?></b></span></div><a class="text-link" href="<?= url('admissions/'.$cycle['slug']) ?>">View details →</a></div></article><?php endforeach?></div><?php endif?></div></section>
<section class="section" id="process"><div class="container"><div class="section-heading centered"><span class="eyebrow">How to apply</span><h2>Seven guided steps. One clear record.</h2></div><div class="process-grid"><?php foreach([['Create your account','Use a unique email and verify it from the secure link.'],['Personal details','Add identity, contact, guardian and address information.'],['Academic history','Enter qualifying examinations and applicable entrance details.'],['Choose preferences','Rank configured programmes within the selected admission cycle.'],['Upload documents','Submit files from the cycle-specific checklist.'],['Review & declare','Check every section, accept the declaration and submit.'],['Track & respond','Follow review, targeted corrections, payment and the final decision.']] as $i=>$step):?><article><i><?= str_pad((string)($i+1),2,'0',STR_PAD_LEFT) ?></i><h3><?= e($step[0]) ?></h3><p><?= e($step[1]) ?></p></article><?php endforeach?></div></div></section>
